// Config plugins are loaded by `expo prebuild` as CommonJS, before any bundler runs.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { withPodfile } = require("expo/config-plugins");

const MARKER = "pods-uuid-collision-fix";

// `Pod::Project` mints Pods-project UUIDs as <sha256-prefix><counter>, taking the
// counter from `@generated_uuids.size` and deliberately skipping the collision
// check because "the Pods project is regenerated each time, and thus all UUIDs
// will have come from this method".
//
// That assumption does not hold for objects created inside a post_install hook.
// `Installer#create_and_save_projects` runs `stabilize_target_uuids` before
// `run_podfile_post_install_hooks`, and that pass leaves `@generated_uuids` empty
// on a project that already holds ~13k objects, so the counter restarts at 0.
//
// react-native's `spm_dependency` -- which @clerk/expo uses to pull in clerk-ios --
// creates its XCRemoteSwiftPackageReference in exactly that hook, so it is handed
// 46EB2E00000000, the root PBXProject's UUID, and silently replaces the project
// object. The written pbxproj then contains no PBXProject at all. Xcode reports
// "The project 'Pods' is damaged and cannot be opened", every pod target is skipped,
// and the app target fails to compile with "no such module 'Expo'" (locally, stale
// artifacts in ios/build hide this until the first never-yet-built module, e.g.
// "no such module 'ExpoStoreReview'").
//
// Skipping UUIDs that are already in use is what upstream Xcodeproj's own
// `generate_available_uuid_list` does; this restores that behaviour.
const PRELUDE = `# >>> ${MARKER} (generated by plugins/with-pods-uuid-collision-fix.js -- do not edit)
require 'set'

module PodsUuidCollisionFix
  def generate_available_uuid_list(count = 100)
    in_use = uuids.to_set
    rounds = 0
    loop do
      super(count)
      @available_uuids.reject! { |uuid| in_use.include?(uuid) }
      break unless @available_uuids.empty?
      rounds += 1
      raise "${MARKER}: no free UUID after #{rounds * count} candidates" if rounds > 10_000
    end
  end
end

Pod::Project.prepend(PodsUuidCollisionFix) unless Pod::Project.ancestors.include?(PodsUuidCollisionFix)
# <<< ${MARKER}

`;

/**
 * Works around a CocoaPods UUID collision that corrupts Pods.xcodeproj whenever a
 * pod declares a Swift Package Manager dependency (@clerk/expo does, via clerk-ios).
 *
 * @type {import("expo/config-plugins").ConfigPlugin}
 */
const withPodsUuidCollisionFix = (config) =>
  withPodfile(config, (podfileConfig) => {
    if (!podfileConfig.modResults.contents.includes(MARKER)) {
      podfileConfig.modResults.contents =
        PRELUDE + podfileConfig.modResults.contents;
    }

    return podfileConfig;
  });

module.exports = withPodsUuidCollisionFix;
